// ---- src/lib/format.ts ----

const krFmt = new Intl.NumberFormat('nb-NO', { maximumFractionDigits: 0 });
/** '12 345 kr' */
export const kr = (n: number) => `${krFmt.format(Math.round(n))} kr`;
export const num = (n: number) => krFmt.format(Math.round(n));

/** '7,5 t' */
export const hrs = (n: number) => `${n.toLocaleString('nb-NO', { maximumFractionDigits: 2 })} t`;

export const MONTHS = ['januar', 'februar', 'mars', 'april', 'mai', 'juni', 'juli', 'august', 'september', 'oktober', 'november', 'desember'];
export const WEEKDAY_SHORT = ['man', 'tir', 'ons', 'tor', 'fre', 'lør', 'søn'];
export const WEEKDAY_LONG = ['mandag', 'tirsdag', 'onsdag', 'torsdag', 'fredag', 'lørdag', 'søndag'];

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

/** 'Oktober' or 'Oktober 2025' outside the current year. */
export function monthName(m: MonthKey, withYear = false): string {
  const [y, mo] = m.split('-').map(Number);
  return cap(MONTHS[mo - 1]) + (withYear ? ` ${y}` : '');
}

/** 'tirsdag 21. oktober' */
export function longDate(d: ISODate): string {
  const [, m, day] = parts(d);
  return `${WEEKDAY_LONG[weekday(d) - 1]} ${day}. ${MONTHS[m - 1]}`;
}

/** 'I dag', 'I morgen', 'I går' or 'tir 21. okt' */
export function relDate(d: ISODate, today: ISODate): string {
  const [, m, day] = parts(d);
  const diff = diffDays(d, today);
  if (diff === 0) return 'I dag';
  if (diff === 1) return 'I morgen';
  if (diff === -1) return 'I går';
  return `${cap(WEEKDAY_SHORT[weekday(d) - 1])} ${day}. ${MONTHS[m - 1].slice(0, 3)}`;
}

// ---- src/lib/pay.ts ----
// What a shift pays: the hourly wage for the paid hours, every supplement whose window the shift overlaps, and overtime.
// Pure functions, so the same numbers show everywhere and are easy to test.

export interface SupplementPay { id: string; name: string; color: string; hours: number; amount: number }
export interface ShiftPay {
  /** Clock hours from start to end. */
  hours: number;
  /** Hours after the unpaid break. */
  paidHours: number;
  wage: number;
  base: number;
  overtime: number;
  supplements: SupplementPay[];
  supplementTotal: number;
  total: number;
}

/** The shift as minutes from midnight on its date; the end is past 1440 for a shift that runs into the next day. */
export function shiftSpan(s: Pick<Shift, 'start_time' | 'end_time'>): { start: number; end: number } | null {
  const start = toMinutes(s.start_time), end = toMinutes(s.end_time);
  if (start === null || end === null) return null;
  return { start, end: end <= start ? end + 1440 : end };
}

export function dayKeys(d: ISODate): Set<DayKey> {
  const keys = new Set<DayKey>([WEEKDAYS[weekday(d) - 1]]);
  if (isHoliday(d)) keys.add('holiday');
  if (isHolidayEve(d)) keys.add('holiday_eve');
  return keys;
}

export const appliesOn = (sup: Pick<Supplement, 'days'>, d: ISODate) => {
  const keys = dayKeys(d);
  return sup.days.some((k) => keys.has(k));
};

/** Minutes of the shift inside the supplement's window. A window belongs to the day it starts on, so a Friday night
 *  window 21:00–06:00 covers Saturday 00:00–06:00 too, and a shift from Thursday evening is checked against Thursday,
 *  Friday (after midnight) and, for long shifts, the day after. */
export function overlapMinutes(shift: Shift, sup: Supplement): number {
  const span = shiftSpan(shift);
  const ws = toMinutes(sup.start_time), we = toMinutes(sup.end_time);
  if (!span || ws === null || we === null) return 0;
  const length = we === ws ? 1440 : we > ws ? we - ws : we + 1440 - ws;
  let total = 0;
  for (let day = -1; day <= 1; day++) {
    if (!appliesOn(sup, addDays(shift.date, day))) continue;
    const from = day * 1440 + ws, to = from + length;
    total += Math.max(0, Math.min(to, span.end) - Math.max(from, span.start));
  }
  return Math.min(total, span.end - span.start);
}

/** The hourly wage on a date: the newest one that has started, or the earliest if the date is before all of them. */
export function wageOn(wages: Wage[], d: ISODate): number {
  if (wages.length === 0) return 0;
  const sorted = [...wages].sort((a, b) => a.from.localeCompare(b.from));
  let w = sorted[0];
  for (const x of sorted) if (x.from <= d) w = x;
  return w.hourly;
}

export function calcShift(shift: Shift, supplements: Supplement[], wages: Wage[]): ShiftPay {
  const span = shiftSpan(shift);
  const wage = wageOn(wages, shift.date);
  const minutes = span ? span.end - span.start : 0;
  const paidMinutes = Math.max(0, minutes - Math.max(0, shift.break_minutes || 0));
  // The break is unpaid but its time of day isn't recorded, so each supplement loses the same share of its hours.
  const paidShare = minutes > 0 ? paidMinutes / minutes : 0;
  const paidHours = paidMinutes / 60;

  const pays: SupplementPay[] = [];
  for (const sup of supplements) {
    if (!sup.active) continue;
    const overlap = overlapMinutes(shift, sup);
    if (overlap <= 0) continue;
    const hours = (overlap / 60) * paidShare;
    let amount: number;
    if (sup.amount_type === 'kr_per_shift') amount = sup.amount;
    else if (sup.amount_type === 'kr_per_hour') amount = hours * sup.amount;
    else amount = hours * Math.max((wage * sup.amount) / 100, sup.min_per_hour ?? 0);
    if (amount > 0) pays.push({ id: sup.id, name: sup.name, color: sup.color, hours, amount });
  }

  const base = paidHours * wage;
  const overtime = paidHours * wage * (Math.max(0, shift.overtime_percent || 0) / 100);
  const supplementTotal = pays.reduce((s, p) => s + p.amount, 0);
  return { hours: minutes / 60, paidHours, wage, base, overtime, supplements: pays, supplementTotal, total: base + overtime + supplementTotal };
}

/** The employer a shift is for; shifts from before employers existed count as the first one. */
export function employerOf(shift: Pick<Shift, 'employer_id'>, employers: Employer[]): Employer | undefined {
  return employers.find((e) => e.id === shift.employer_id) ?? employers[0];
}

/** A shift's pay with its own employer's wage and supplements; a sick shift at the sick-pay share. */
export function payOf(shift: Shift, setup: Setup): ShiftPay {
  const emp = employerOf(shift, setup.employers);
  const p = emp ? calcShift(shift, setup.supplements.filter((x) => x.employer_id === emp.id), emp.wages) : calcShift(shift, [], []);
  if (shift.status !== 'sick') return p;
  const k = (setup.sickPercent ?? 100) / 100;
  const supplements = p.supplements.map((x) => ({ ...x, amount: x.amount * k }));
  return { ...p, base: p.base * k, overtime: p.overtime * k, supplements, supplementTotal: p.supplementTotal * k, total: p.total * k };
}

export interface Summary {
  count: number;
  hours: number;
  base: number;
  overtime: number;
  supplementTotal: number;
  total: number;
  /** Per supplement, largest first. Supplements with the same name at different employers are added together. */
  bySupplement: SupplementPay[];
  /** Total per employer id. */
  byEmployer: Map<string, number>;
}

export function summarize(shifts: Shift[], setup: Setup): Summary {
  const by = new Map<string, SupplementPay>();
  const sum: Summary = { count: 0, hours: 0, base: 0, overtime: 0, supplementTotal: 0, total: 0, bySupplement: [], byEmployer: new Map() };
  for (const s of shifts) {
    const p = payOf(s, setup);
    sum.count++;
    sum.hours += p.paidHours;
    sum.base += p.base;
    sum.overtime += p.overtime;
    sum.supplementTotal += p.supplementTotal;
    sum.total += p.total;
    const emp = employerOf(s, setup.employers);
    if (emp) sum.byEmployer.set(emp.id, (sum.byEmployer.get(emp.id) ?? 0) + p.total);
    for (const x of p.supplements) {
      const key = x.name.trim().toLowerCase();
      const acc = by.get(key) ?? { ...x, hours: 0, amount: 0 };
      acc.hours += x.hours;
      acc.amount += x.amount;
      by.set(key, acc);
    }
  }
  sum.bySupplement = [...by.values()].sort((a, b) => b.amount - a.amount);
  return sum;
}

/** The target employer with the source's wages, shift types, pay day and supplements: copies with new ids, so changing
 *  one employer later never changes the other. The target keeps its own name and colour. */
export function copySetup(source: Employer, supplements: Supplement[], target: Employer, newId: () => string): { employer: Employer; supplements: Supplement[] } {
  return {
    employer: {
      ...target,
      wages: source.wages.map((w) => ({ ...w })),
      templates: source.templates.map((t) => ({ ...t, id: newId() })),
      pay_day: source.pay_day,
      pay_delay: source.pay_delay,
    },
    supplements: supplements.filter((x) => x.employer_id === source.id).map((x) => ({ ...x, days: [...x.days], id: newId(), employer_id: target.id })),
  };
}

/** When a shift is over, as a local Date: worked shifts count as earned, the rest as planned. */
export function shiftEnd(s: Shift): Date {
  const span = shiftSpan(s);
  const [y, m, d] = s.date.split('-').map(Number);
  return new Date(y, m - 1, d, 0, span ? span.end : 1440);
}

export const inMonth = (shifts: Shift[], m: MonthKey) => shifts.filter((s) => monthOf(s.date) === m);

/** Dag, Kveld or Natt from the times alone, for a label on each shift. */
export function shiftKind(s: Pick<Shift, 'start_time' | 'end_time'>): 'Dag' | 'Kveld' | 'Natt' {
  const span = shiftSpan(s);
  if (!span) return 'Dag';
  if (span.end > 1440 + 120 || span.start >= 20 * 60) return 'Natt';
  if (span.start >= 12 * 60) return 'Kveld';
  return 'Dag';
}

/** One payment into the account: an employer's pay day in a month, and what it is for. */
export interface Payout {
  employerId: string;
  date: ISODate;
  /** Hourly wage for the shifts this payment covers. */
  wage: number;
  /** Supplements and overtime (often for the month before). */
  variable: number;
  /** Holiday pay (feriepenger), in June, for last year. */
  holiday: number;
  total: number;
}

/** What each employer pays in `month`: the wage and the supplements according to its pay delay, plus holiday pay in
 *  June. Months are counted from the shift's date. */
export function payoutsIn(month: MonthKey, shifts: Shift[], setup: Setup, holidayPercent: number): Payout[] {
  const lines = new Map<string, Payout>();
  const line = (e: Employer) => {
    let l = lines.get(e.id);
    if (!l) {
      const day = Math.min(Math.max(1, e.pay_day || 12), daysInMonth(month));
      l = { employerId: e.id, date: `${month}-${String(day).padStart(2, '0')}`, wage: 0, variable: 0, holiday: 0, total: 0 };
      lines.set(e.id, l);
    }
    return l;
  };
  const prev = addMonths(month, -1);
  const year = Number(month.slice(0, 4));
  const june = month.slice(5) === '06';
  for (const s of shifts) {
    const m = monthOf(s.date);
    const lastYear = june && s.date.startsWith(`${year - 1}-`);
    if (m !== month && m !== prev && !lastYear) continue;
    const emp = employerOf(s, setup.employers);
    if (!emp) continue;
    const p = payOf(s, setup);
    if (lastYear) line(emp).holiday += (p.total * holidayPercent) / 100;
    const delay = emp.pay_delay ?? 'supplements';
    if (addMonths(m, delay === 'all' ? 1 : 0) === month) line(emp).wage += p.base;
    if (addMonths(m, delay === 'none' ? 0 : 1) === month) line(emp).variable += p.total - p.base;
  }
  return [...lines.values()]
    .map((l) => ({ ...l, total: l.wage + l.variable + l.holiday }))
    .filter((l) => l.total > 0)
    .sort((a, b) => a.date.localeCompare(b.date));
}

/** Holiday pay earned in a year (paid in June the year after). */
export function holidayPayEarned(year: number, shifts: Shift[], setup: Setup, holidayPercent: number): number {
  return (summarize(shifts.filter((s) => s.date.startsWith(`${year}-`)), setup).total * holidayPercent) / 100;
}

/** The shifts in `source` repeated `times` more times, each `periodDays` later (a week, or a rota of several weeks).
 *  A copy that would land on a shift she already has (same day, start and employer) is left out. */
export function repeatShifts(source: Shift[], periodDays: number, times: number, existing: Shift[], newId: () => string): Shift[] {
  const taken = new Set(existing.map((s) => `${s.date}|${s.start_time}|${s.employer_id}`));
  const out: Shift[] = [];
  for (let k = 1; k <= times; k++) {
    for (const s of source) {
      const date = addDays(s.date, k * periodDays);
      const key = `${date}|${s.start_time}|${s.employer_id}`;
      if (taken.has(key)) continue;
      taken.add(key);
      out.push({ ...s, id: newId(), date, status: 'worked', note: s.note });
    }
  }
  return out;
}

// ---- plan.ts ----
// Which reminders are due now, worked out from the rows alone so it is easy to test. Times are Norwegian wall-clock
// time (Europe/Oslo), the same as the shifts. Every reminder has a key; the function claims a key before sending, so
// a reminder is never sent twice however often it runs.

export interface OwnerRows {
  ownerId: string;
  settings: Record<string, unknown> | null;
  employers: Employer[];
  supplements: Supplement[];
  /** Shifts from yesterday on (Oslo time). */
  shifts: Shift[];
}

export interface Message { key: string; title: string; body: string; url: string; tag: string }

/** Oslo date and minutes after midnight for an instant. */
export function osloNow(now: number): { date: ISODate; minutes: number } {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Oslo', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  }).formatToParts(new Date(now)).map((x) => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, minutes: Number(p.hour) * 60 + Number(p.minute) };
}

/** Wall-clock minutes on one scale, so times on different days compare. */
const at = (date: ISODate, minutes: number) => {
  const [y, m, d] = date.split('-').map(Number);
  return Date.UTC(y, m - 1, d) / 60_000 + minutes;
};

const AFTER = 30; // minutes after a shift ends
const LATE = 180; // a reminder more than this late is skipped rather than sent

export function planOwner(o: OwnerRows, now: number): Message[] {
  const s = (o.settings ?? {}) as { onboarded?: boolean; reminders?: Record<string, boolean>; sick_percent?: number };
  if (!s.onboarded) return [];
  const rules = { after_shift: true, weekly: true, month: true, ...(s.reminders ?? {}) };
  const { date: today, minutes } = osloNow(now);
  const nowAt = at(today, minutes);
  const out: Message[] = [];

  if (rules.after_shift) {
    for (const sh of o.shifts) {
      const span = shiftSpan(sh);
      if (!span || sh.status === 'sick') continue;
      const due = at(sh.date, span.end) + AFTER;
      if (nowAt < due || nowAt > due + LATE) continue;
      const pay = payOf(sh, { employers: o.employers, supplements: o.supplements, sickPercent: s.sick_percent });
      out.push({
        key: `after:${sh.id}:${sh.date}:${sh.end_time}`,
        title: 'Vakta er ferdig 💜',
        body: `+${kr(pay.total)} tjent (${sh.start_time}–${sh.end_time}). Stemmer tidene? Trykk for å sjekke.`,
        url: '/vakter', tag: `after-${sh.id}`,
      });
    }
  }

  const evening = minutes >= 18 * 60 && minutes < 21 * 60;
  if (rules.weekly && evening && weekday(today) === 7) {
    const from = addDays(today, 1), to = addDays(today, 7);
    if (!o.shifts.some((x) => x.date >= from && x.date <= to)) {
      out.push({ key: `week:${from}`, title: 'Ny uke i morgen 🗓️', body: 'Du har ingen vakter lagt inn neste uke. Legg dem inn nå, så ser du hva uka gir.', url: '/vakter', tag: 'week' });
    }
  }

  const month = monthOf(today);
  if (rules.month && evening && Number(today.slice(8)) === daysInMonth(month) - 5) {
    const next = addMonths(month, 1);
    if (!o.shifts.some((x) => monthOf(x.date) === next)) {
      const name = MONTHS[Number(next.slice(5)) - 1];
      out.push({ key: `month:${next}`, title: `Turnusen for ${name}? ✨`, body: `Legg inn vaktene for ${name}, så ser du hva måneden gir.`, url: '/vakter', tag: 'month' });
    }
  }
  return out;
}

export const TEST_MESSAGE = { title: 'Vakt 🔔', body: 'Varsler virker på denne enheten.', url: '/', tag: 'test' };

/** The first day of shifts the plan needs: yesterday in Oslo (a night shift that ends this morning). */
export const shiftsFrom = (now: number) => addDays(osloNow(now).date, -1);

// ---- push.ts ----
// Web Push (RFC 8030) with payload encryption (RFC 8291, aes128gcm) and VAPID (RFC 8292), on WebCrypto, so it runs in
// Deno (the edge function), browsers and Node (the tests). Vakt's own copy of the code Ledger and Home Memory use,
// so the apps never depend on each other.

const enc = new TextEncoder();
/** Bytes backed by a plain ArrayBuffer, which is what WebCrypto and fetch take. */
type Bytes = Uint8Array<ArrayBuffer>;

export function b64uToBytes(s: string): Bytes {
  const b = s.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (s.length % 4)) % 4);
  return Uint8Array.from(atob(b), (c) => c.charCodeAt(0));
}
export function bytesToB64u(bytes: Bytes): string {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const concat = (...parts: Bytes[]) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
};

async function hkdf(salt: Bytes, ikm: Bytes, info: Bytes, bytes: number): Promise<Bytes> {
  const key = await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, key, bytes * 8));
}

export type EncryptOptions = { salt?: Bytes; senderKeys?: CryptoKeyPair };

/** Encrypts `payload` for a push subscription. Returns the request body (header + one record). */
export async function encryptPayload(payload: Bytes, uaPublic: Bytes, authSecret: Bytes, opts: EncryptOptions = {}): Promise<Bytes> {
  if (uaPublic.length !== 65 || uaPublic[0] !== 4) throw new Error('bad subscription key');
  if (payload.length > 3993) throw new Error('payload too large'); // one 4096-byte record: 4096 - 16 tag - 1 delimiter - 86 header
  const salt = opts.salt ?? crypto.getRandomValues(new Uint8Array(16));
  const sender = opts.senderKeys ?? (await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']));
  const asPublic = new Uint8Array(await crypto.subtle.exportKey('raw', sender.publicKey));
  const uaKey = await crypto.subtle.importKey('raw', uaPublic, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
  const ecdh = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: uaKey }, sender.privateKey, 256));
  const keyInfo = concat(enc.encode('WebPush: info\0'), uaPublic, asPublic);
  const ikm = await hkdf(authSecret, ecdh, keyInfo, 32);
  const cek = await hkdf(salt, ikm, enc.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, enc.encode('Content-Encoding: nonce\0'), 12);
  const aes = await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const cipher = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce }, aes, concat(payload, new Uint8Array([2]))));
  const rs = new Uint8Array([0, 0, 0x10, 0]); // 4096, big endian
  return concat(salt, rs, new Uint8Array([asPublic.length]), asPublic, cipher);
}

/** VAPID `Authorization` header value for a push endpoint. `privateD` is the 32-byte private scalar, `publicKey` the 65-byte point. */
export async function vapidAuthorization(endpoint: string, subject: string, publicKey: Bytes, privateD: Bytes, now = Date.now()): Promise<string> {
  const key = await crypto.subtle.importKey(
    'jwk',
    { kty: 'EC', crv: 'P-256', x: bytesToB64u(publicKey.slice(1, 33)), y: bytesToB64u(publicKey.slice(33, 65)), d: bytesToB64u(privateD) },
    { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign'],
  );
  const part = (o: unknown) => bytesToB64u(enc.encode(JSON.stringify(o)));
  const signingInput = `${part({ typ: 'JWT', alg: 'ES256' })}.${part({ aud: new URL(endpoint).origin, exp: Math.floor(now / 1000) + 12 * 3600, sub: subject })}`;
  const sig = new Uint8Array(await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, enc.encode(signingInput)));
  return `vapid t=${signingInput}.${bytesToB64u(sig)}, k=${bytesToB64u(publicKey)}`;
}

export type PushSub = { endpoint: string; p256dh: string; auth: string };

/** Builds and sends one push. Resolves with the push service's HTTP status. `ttl`: seconds the push service keeps trying a device that is off. */
export async function sendPush(sub: PushSub, payload: unknown, vapid: { subject: string; publicKey: string; privateKey: string }, ttl = 86400, fetchImpl: typeof fetch = fetch): Promise<number> {
  const body = await encryptPayload(enc.encode(JSON.stringify(payload)), b64uToBytes(sub.p256dh), b64uToBytes(sub.auth));
  const res = await fetchImpl(sub.endpoint, {
    method: 'POST',
    headers: {
      Authorization: await vapidAuthorization(sub.endpoint, vapid.subject, b64uToBytes(vapid.publicKey), b64uToBytes(vapid.privateKey)),
      'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream', TTL: String(ttl), Urgency: 'high',
    },
    body,
  });
  return res.status;
}

/** 404 and 410 mean the subscription is gone for good: forget it. */
export const isGone = (status: number) => status === 404 || status === 410;

/** Push services browsers use. The function only ever posts to these, whatever a device row says. */
const PUSH_HOSTS = [/^fcm\.googleapis\.com$/, /^([a-z0-9-]+\.)*push\.services\.mozilla\.com$/, /^web\.push\.apple\.com$/, /^[a-z0-9-]+\.notify\.windows\.com$/];
export function isPushEndpoint(endpoint: string): boolean {
  try {
    const u = new URL(endpoint);
    return u.protocol === 'https:' && !u.port && PUSH_HOSTS.some((h) => h.test(u.hostname));
  } catch {
    return false;
  }
}

// ---- handler ----
const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};
const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });

type Vapid = { publicKey: string; privateKey: string; subject: string };
type Device = { id: string; owner_id: string; endpoint: string; p256dh: string; auth: string };

async function deliver(admin: SupabaseClient, devices: Device[], message: unknown, vapid: Vapid) {
  let sent = 0;
  const gone: string[] = [];
  await Promise.all(devices.map(async (d) => {
    if (!isPushEndpoint(d.endpoint)) return;
    try {
      const status = await sendPush(d, message, vapid, 6 * 3600);
      if (status >= 200 && status < 300) sent++;
      else if (isGone(status)) gone.push(d.id);
      else console.error('push refused', status);
    } catch (e) {
      console.error('push failed', e instanceof Error ? e.message : e);
    }
  }));
  if (gone.length) await admin.from('vakt_push_devices').delete().in('id', gone);
  return sent;
}

async function runDue(req: Request, vapid: Vapid) {
  const secret = Deno.env.get('VAKT_CRON_SECRET') ?? Deno.env.get('CRON_SECRET');
  if (!secret) return json({ error: 'not_configured' }, 503);
  if (req.headers.get('x-cron-secret') !== secret) return json({ error: 'unauthorized' }, 401);
  const admin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
  const now = Date.now();
  await admin.from('vakt_notify_status').upsert({ id: true, last_run: new Date(now).toISOString() });

  const { data: devices, error } = await admin.from('vakt_push_devices').select('id, owner_id, endpoint, p256dh, auth');
  if (error) return json({ error: 'not_installed' }, 500);
  if (!devices?.length) return json({ due: 0, sent: 0 });
  const owners: string[] = [...new Set((devices as Device[]).map((d) => d.owner_id))];
  const [profiles, employers, supplements, shifts] = await Promise.all([
    admin.from('vakt_profiles').select('owner_id, settings').in('owner_id', owners),
    admin.from('vakt_employers').select('*').in('owner_id', owners),
    admin.from('vakt_supplements').select('*').in('owner_id', owners),
    admin.from('vakt_shifts').select('*').in('owner_id', owners).gte('date', shiftsFrom(now)).order('date'),
  ]);
  type Row = Record<string, unknown> & { owner_id: string };
  const of = (rows: unknown[] | null, id: string) => ((rows ?? []) as Row[]).filter((r) => r.owner_id === id);

  let due = 0, sent = 0;
  for (const ownerId of owners) {
    const rows: OwnerRows = {
      ownerId,
      settings: (of(profiles.data, ownerId)[0]?.settings ?? null) as Record<string, unknown> | null,
      employers: of(employers.data, ownerId) as unknown as Employer[],
      supplements: of(supplements.data, ownerId).map((x) => ({ ...x, amount: Number(x.amount), min_per_hour: x.min_per_hour === null ? null : Number(x.min_per_hour) })) as unknown as Supplement[],
      shifts: of(shifts.data, ownerId) as unknown as Shift[],
    };
    const messages = planOwner(rows, now);
    due += messages.length;
    if (!messages.length) continue;
    // Claim first: only keys inserted now are sent, so overlapping runs never send the same reminder twice.
    const { data: claimed } = await admin.from('vakt_push_sent')
      .upsert(messages.map((m) => ({ owner_id: ownerId, key: m.key })), { onConflict: 'owner_id,key', ignoreDuplicates: true })
      .select('key');
    const mine = (devices as Device[]).filter((d) => d.owner_id === ownerId);
    const won = new Set(((claimed ?? []) as { key: string }[]).map((c) => c.key));
    for (const m of messages.filter((x) => won.has(x.key))) {
      const { key: _key, ...payload } = m;
      sent += await deliver(admin, mine, payload, vapid);
    }
  }
  await admin.from('vakt_push_sent').delete().lt('sent_at', new Date(now - 60 * 86_400_000).toISOString());
  return json({ due, sent });
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);

  const publicKey = Deno.env.get('VAPID_PUBLIC_KEY');
  const privateKey = Deno.env.get('VAPID_PRIVATE_KEY');
  if (!publicKey || !privateKey) return json({ error: 'not_configured' }, 503);
  const vapid = { publicKey, privateKey, subject: Deno.env.get('VAPID_SUBJECT') ?? 'mailto:admin@example.com' };

  let body: { mode?: string; op?: string };
  try { body = await req.clone().json(); } catch { return json({ error: 'bad_request' }, 400); }
  if (body?.mode === 'due') return await runDue(req, vapid);

  // Everything else is for a signed-in person; row level security decides what they may see.
  const auth = req.headers.get('Authorization');
  if (!auth) return json({ error: 'unauthorized' }, 401);
  const url = Deno.env.get('SUPABASE_URL')!;
  const asCaller = createClient(url, Deno.env.get('SUPABASE_ANON_KEY')!, { global: { headers: { Authorization: auth } } });
  const { data: who } = await asCaller.auth.getUser();
  if (!who?.user?.id) return json({ error: 'unauthorized' }, 401);

  if (body?.op === 'status') {
    const admin = createClient(url, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
    const { data } = await admin.from('vakt_notify_status').select('last_run').maybeSingle();
    return json({ publicKey, lastRun: data?.last_run ?? null });
  }
  if (body?.op === 'test') {
    const { data: devices, error } = await asCaller.from('vakt_push_devices').select('id, owner_id, endpoint, p256dh, auth');
    if (error) return json({ error: 'not_installed' }, 500);
    const admin = createClient(url, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);
    return json({ sent: await deliver(admin, (devices ?? []) as Device[], TEST_MESSAGE, vapid), devices: devices?.length ?? 0 });
  }
  return json({ error: 'bad_request' }, 400);
});
